// Golementor Pro: the features of upstream Pro 4.3.0 (GPL-3.0, see NOTICE) ported onto the
// Golementor back end. The editor side ships Pro's built editor bundle, its Backbone templates,
// control types and configs (internal/server/gowebeditor/pro-*.gz, generated by
// scratchpad pro-tools/gen_pro.py from a lab capture); the server side here answers Pro's ajax
// actions and REST routes, serves Pro's document types (popup, loop-item, global widget, theme
// documents) and prints Pro's front-end assets. Widget rendering lives in internal/builder
// (widgets_pro_*.go, dynamic_*.go). Nothing of upstream's licensing, Connect or cloud services is
// used: every feature is simply enabled.

//go:embed gowebeditor/pro-preview-styles.json
var gweProPreviewStylesJSON []byte

// gweProStore holds the decoded Pro editor data.
type gweProStore struct {
	proConfig        map[string]any
	appProConfig     json.RawMessage
	configPatch      map[string]json.RawMessage
	panelCategories  json.RawMessage
	displayCondsLine json.RawMessage
	templates        string
	frontCfg         map[string]any
	i18n             json.RawMessage
	previewStyles    [][2]string
}

var gwePro gweProStore

// gweProDocTypes are the document types Pro adds (plus the library types it extends).
var gweProDocTypes = []string{"wp-page", "wp-post", "kit", "section", "container", "page", "popup", "header", "footer",
	"single-post", "single-page", "single", "archive", "search-results", "error-404", "loop-item", "widget"}

// gweProLoad replaces the free editor data with Pro's and patches the editor shell. It runs once,
// from gweData.
func gweProLoad(g *gweStore) {
	must := func(err error) {
		if err != nil {
			panic("gowebeditor pro data: " + err.Error())
		}
	}
	var ed struct {
		ProConfig               map[string]any             `json:"proConfig"`
		AppProConfig            json.RawMessage            `json:"appProConfig"`
		ConfigPatch             map[string]json.RawMessage `json:"configPatch"`
		PanelCategories         json.RawMessage            `json:"panelCategories"`
		DisplayConditionsInline json.RawMessage            `json:"displayConditionsInline"`
	}
	must(json.Unmarshal(gweRead("pro-editor.json.gz"), &ed))
	gwePro.proConfig = ed.ProConfig
	gwePro.appProConfig = ed.AppProConfig
	gwePro.configPatch = ed.ConfigPatch
	gwePro.panelCategories = ed.PanelCategories
	gwePro.displayCondsLine = ed.DisplayConditionsInline
	gwePro.templates = string(gweRead("pro-templates.html.gz"))
	must(json.Unmarshal(gweRead("pro-frontend-config.json.gz"), &gwePro.frontCfg))
	gwePro.i18n = gweRead("pro-i18n.json.gz")
	must(json.Unmarshal(gweProPreviewStylesJSON, &gwePro.previewStyles))

	g.widgetsCfg = gweRead("pro-widgets-config.json.gz")
	g.docWidgets = gweRead("pro-doc-widgets.json.gz")
	for _, t := range gweProDocTypes {
		m := map[string]json.RawMessage{}
		must(json.Unmarshal(gweRead("pro-doc-"+t+".json.gz"), &m))
		g.docs[t] = m
	}
	g.shell = gweProPatchShell(g.shell, gwePro.templates)
	for _, t := range []string{"popup", "loop-item"} {
		var st struct {
			Controls json.RawMessage `json:"controls"`
		}
		if json.Unmarshal(g.docs[t]["settings"], &st) == nil && len(st.Controls) > 0 {
			builder.RegisterDocumentStack(t, st.Controls)
		}
	}
}

// gweProPatchShell adds Pro's stylesheet, scripts and Backbone templates to the editor shell, in
// the places the upstream plugin enqueues them.
func gweProPatchShell(h, templates string) string {
	insertAfterTag := func(h, id, tag, add string) string {
		re := regexp.MustCompile(`(?s)<` + tag + `[^>]*\bid=['"]` + regexp.QuoteMeta(id) + `['"][^>]*>(?:.*?</` + tag + `>)?`)
		loc := re.FindStringIndex(h)
		if loc == nil {
			if tag == "link" {
				re = regexp.MustCompile(`<link[^>]*\bid=['"]` + regexp.QuoteMeta(id) + `['"][^>]*/?>`)
				loc = re.FindStringIndex(h)
			}
			if loc == nil {
				panic("gowebeditor pro: shell anchor " + id + " not found")
			}
		}
		return h[:loc[1]] + "\n" + add + h[loc[1]:]
	}
	pro := func(rel string) string { return "@@GWEASSETS@@pro/" + rel + "?ver=@@VER@@" }
	h = insertAfterTag(h, "e-theme-ui-dark-css", "link",
		"<link rel='stylesheet' id='elementor-pro-css' href='"+pro("css/editor.min.css")+"' media='all' />")
	h = insertAfterTag(h, "wp-i18n-js-after", "script",
		`<script id="elementor-pro-app-js-before">`+"\n@@CFG:elementor-pro-app-js-before@@\n</script>")
	h = insertAfterTag(h, "elementor-editor-document-js", "script",
		`<script id="elementor-pro-js-before">`+"\n@@CFG:elementor-pro-js-before@@\n</script>\n"+
			`<script src="`+pro("js/editor.min.js")+`" id="elementor-pro-js"></script>`)
	h = insertAfterTag(h, "media-upload-js", "script",
		`<script id="e-display-conditions-js-before">`+"\n@@CFG:e-display-conditions-js-before@@\n</script>\n"+
			`<script src="`+pro("js/display-conditions.min.js")+`" id="e-display-conditions-js"></script>`)
	h = insertAfterTag(h, "elementor-v2-editor-site-navigation-js", "script",
		`<script src="`+pro("js/packages/editor-site-navigation-extended/editor-site-navigation-extended.min.js")+`" id="elementor-v2-editor-site-navigation-extended-js"></script>`+"\n"+
			`<script src="`+pro("js/packages/license-api/license-api.min.js")+`" id="elementor-v2-license-api-js"></script>`+"\n"+
			`<script src="`+pro("js/packages/editor-documents-extended/editor-documents-extended.min.js")+`" id="elementor-v2-editor-documents-extended-js"></script>`)
	// Templates go after the last free template.
	last := strings.LastIndex(h, `<script type="text/template" id="tmpl-`)
	if last < 0 {
		panic("gowebeditor pro: no templates in shell")
	}
	end := strings.Index(h[last:], "</script>")
	if end < 0 {
		panic("gowebeditor pro: template end")
	}
	pos := last + end + len("</script>")
	return h[:pos] + "\n" + templates + h[pos:]
}

// gweProEditorParts fills the inline scripts Pro adds to the editor page.
func (s *Server) gweProEditorParts(c *gin.Context, p *store.Post, parts map[string]string) {
	d := gweData()
	_ = d
	cfg := make(map[string]any, len(gwePro.proConfig)+4)
	for k, v := range gwePro.proConfig {
		cfg[k] = v
	}
	cfg["widget_templates"] = s.gweProGlobalWidgetTemplates(c)
	cfg["forms"] = s.gweProFormsEditorConfig()
	cfg["loopFilter"] = map[string]any{"mainQueryPostType": "post", "nonce": s.nonce(c, "wp_rest")}
	cfg["eSearch"] = map[string]any{"nonce": s.nonce(c, "wp_rest")}
	parts["elementor-pro-js-before"] = "var elementorProEditorConfig = " + gweJSON(cfg) + ";\n" +
		"wp.i18n.setLocaleData( " + string(gwePro.i18n) + ", 'elementor-pro' );"
	if tr := s.gweScriptTranslations(c); len(tr) > 0 { // Pro has no pack of its own; most strings are shared
		parts["elementor-pro-js-before"] += "\nwp.i18n.setLocaleData( " + string(tr) + ", 'elementor-pro' );"
	}
	parts["elementor-pro-app-js-before"] = "var elementorAppProConfig = " + string(gwePro.appProConfig) + ";"
	parts["e-display-conditions-js-before"] = "window.ElementorProDisplayConditions = " + string(gwePro.displayCondsLine) + ";"
}

// gweProEditorConfig adds Pro's keys to the editor config: dynamic tags, display conditions, the
// extra control types, the elements' Pro controls (motion effects, sticky, custom CSS, attributes),
// the library document types.
func (s *Server) gweProEditorConfig(c *gin.Context, cfg map[string]any) {
	for k, v := range gwePro.configPatch {
		cfg[k] = v
	}
	cfg["promotionWidgets"] = []any{}
	s.gweCustomIconsEditorConfig(c, cfg) // gap-widgets: Custom Icons in the icon library (gwe_custom_icons.go)
	// Custom Fonts: listed in the font control's "Custom Fonts" group.
	if fonts := s.gweProFonts(); len(fonts) > 0 {
		var ctrls map[string]json.RawMessage
		if json.Unmarshal(gwePro.configPatch["controls"], &ctrls) == nil {
			var font map[string]any
			if json.Unmarshal(ctrls["font"], &font) == nil {
				opts, _ := font["options"].(map[string]any)
				if opts == nil {
					opts = map[string]any{}
				}
				for _, f := range fonts {
					opts[f.Family] = "custom"
				}
				font["options"] = opts
				ctrls["font"], _ = json.Marshal(font)
				b, _ := json.Marshal(ctrls)
				cfg["controls"] = json.RawMessage(b)
			}
		}
	}
	if u := currentUser(c); u != nil {
		if m, ok := cfg["user"].(map[string]any); ok {
			m["restrictions"] = s.gweProUserRestrictions(u)
		}
	}
}

// gweProDocConfig completes a document config for Pro document types: theme documents get the
// conditions block the editor's "Display Conditions" dialog reads, popups their display settings.
func (s *Server) gweProDocConfig(c *gin.Context, p *store.Post, out map[string]any) {
	typ := gweDocType(p)
	if tb, ok := out["theme_builder"].(json.RawMessage); ok {
		var m map[string]any
		if json.Unmarshal(tb, &m) == nil {
			conds := []map[string]any{}
			for i, cond := range gweConditionsOf(p) {
				parts := strings.SplitN(cond, "/", 4)
				for len(parts) < 4 {
					parts = append(parts, "")
				}
				conds = append(conds, map[string]any{"_id": "c" + strconv.Itoa(i), "type": parts[0], "name": parts[1], "sub_name": parts[2], "sub_id": parts[3]})
			}
			loc := typ
			switch typ {
			case "single-post", "single-page", "single", "archive", "search-results", "error-404", "single-product", "product-archive":
				loc = "single"
				if typ == "archive" || typ == "search-results" || typ == "product-archive" {
					loc = "archive"
				}
			}
			m["settings"] = map[string]any{"template_type": typ, "location": loc, "conditions": conds}
			m["is_theme_template"] = true
			b, _ := json.Marshal(m)
			out["theme_builder"] = json.RawMessage(b)
		}
	}
	if typ == "popup" {
		if ds, ok := out["displaySettings"].(json.RawMessage); ok {
			var m map[string]map[string]any
			if json.Unmarshal(ds, &m) == nil {
				saved := gweProPopupDisplaySettings(p)
				for group := range m {
					settings, _ := m[group]["settings"].(map[string]any)
					if settings == nil {
						settings = map[string]any{}
					}
					if sv, ok := saved[group].(map[string]any); ok {
						for k, v := range sv {
							settings[k] = v
						}
					}
					m[group]["settings"] = settings
				}
				b, _ := json.Marshal(m)
				out["displaySettings"] = json.RawMessage(b)
			}
		}
	}
	if w, ok := out["widgets"].(json.RawMessage); ok {
		out["widgets"] = gweProDocWidgets(w)
	}
	if typ == "widget" { // global widget: the panel edits the single widget
		out["post_type_title"] = "Global Widget"
	}
	gwePopupEditorDocConfig(p, out) // gap-widgets: popup preview dialog styling (gwe_popup_preview.go)
}

// gweProPopupDisplaySettings reads a popup's triggers and timing (_elementor_popup_display_settings).
func gweProPopupDisplaySettings(p *store.Post) map[string]any {
	out := map[string]any{}
	switch v := p.Meta["_elementor_popup_display_settings"].(type) {
	case map[string]any:
		for k, x := range v {
			out[k] = x
		}
	case string:
		_ = json.Unmarshal([]byte(v), &out)
	}
	return out
}

// gweProGlobalWidgetTemplates lists the saved global widgets (library templates of type widget).
func (s *Server) gweProGlobalWidgetTemplates(ctx context.Context) map[string]any {
	out := map[string]any{}
	rows, err := s.store.Pool.Query(ctx, `SELECT id, title, meta->>'_elementor_data' FROM posts WHERE type = $1
		AND meta->>'_elementor_template_type' = 'widget' AND status IN ('publish','private','draft') ORDER BY id`, gweLibrary)
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var id int64
		var title string
		var data *string
		if rows.Scan(&id, &title, &data) != nil || data == nil {
			continue
		}
		els, err := builder.ParseElements([]byte(*data))
		if err != nil || len(els) == 0 || els[0] == nil || els[0].WidgetType == "" {
			continue
		}
		out[itoa64(id)] = map[string]any{"elType": "widget", "title": title, "widgetType": els[0].WidgetType}
	}
	return out
}

// --- ajax actions ------------------------------------------------------------------------------

// gweProAction handles the ajax actions Pro registers; handled is false for other actions.
func (s *Server) gweProAction(c *gin.Context, action string, data map[string]any, raw json.RawMessage, editorID int64) (any, bool, error) {
	if out, ok, err := s.gweIntegrationsAction(c, action, data, editorID); ok { // gap-integrations: form integrations, Stripe tax rates
		return out, true, err
	}
	switch action {
	case "render_tags":
		out, err := s.gweProRenderTags(c, data, editorID)
		return out, true, err
	case "pro_panel_posts_control_filter_autocomplete", "pro_panel_posts_control_filter_autocomplete_deprecated":
		out, err := s.gweProAutocomplete(c, data)
		return out, true, err
	case "query_control_value_titles", "query_control_value_titles_deprecated":
		out, err := s.gweProValueTitles(c, data)
		return out, true, err
	case "pro_popup_save_display_settings":
		p, err := s.gwePostFor(c, editorID, "edit_post")
		if err != nil {
			return nil, true, err
		}
		settings, _ := data["settings"].(map[string]any)
		p.Meta["_elementor_popup_display_settings"] = settings
		return true, true, s.store.UpdatePost(c, p, currentUser(c).ID)
	case "pro_theme_builder_save_conditions":
		p, err := s.gwePostFor(c, editorID, "edit_post")
		if err != nil {
			return nil, true, err
		}
		var conds []string
		for _, item := range asAnyList(data["conditions"]) {
			m, _ := item.(map[string]any)
			if m == nil {
				continue
			}
			parts := []string{gweStr(m["type"]), gweStr(m["name"]), gweStr(m["sub_name"]), gweStr(m["sub_id"])}
			cond := strings.TrimRight(strings.Join(parts, "/"), "/")
			if gweValidRule(cond) {
				conds = append(conds, cond)
			}
		}
		p.Meta["_gwe_conditions"] = conds
		if err := s.store.UpdatePost(c, p, currentUser(c).ID); err != nil {
			return nil, true, err
		}
		s.gweAfterPartSave(c, p)
		s.purgeAll(c)
		return true, true, nil
	case "pro_theme_builder_conditions_check_conflicts":
		return s.gweProConditionConflicts(c, data, editorID), true, nil
	case "pro_forms_panel_action_data", "pro_assets_manager_panel_action_data":
		return map[string]any{}, true, nil
	case "pro_assets_manager_custom_icon_upload":
		return nil, true, gweFail(http.StatusBadRequest, "Upload custom icon sets under Pursae Web Builder › Custom Icons.")
	case "app_site_editor_template_types":
		return []any{}, true, nil
	case "display_conditions_set_cache_notice_status", "screenshot_save", "screenshot_failed", "screenshot_delete",
		"elementor_site_mailer_campaign":
		return true, true, nil
	}
	return nil, false, nil
}

func gweStr(v any) string {
	switch t := v.(type) {
	case string:
		return t
	case json.Number:
		return t.String()
	case float64:
		return strconv.FormatFloat(t, 'f', -1, 64)
	}
	return ""
}

func asAnyList(v any) []any {
	l, _ := v.([]any)
	return l
}

// gweProConditionConflicts tells the editor which other theme part already claims a condition.
func (s *Server) gweProConditionConflicts(c *gin.Context, data map[string]any, editorID int64) string {
	m, _ := data["condition"].(map[string]any)
	if m == nil {
		return ""
	}
	parts := []string{gweStr(m["type"]), gweStr(m["name"]), gweStr(m["sub_name"]), gweStr(m["sub_id"])}
	cond := strings.TrimRight(strings.Join(parts, "/"), "/")
	if parts[0] != "include" {
		return ""
	}
	p, err := s.store.GetPost(c, editorID)
	if err != nil {
		return ""
	}
	typ := gweDocType(p)
	posts, err := s.gwePartPosts(c, gwePartTheme(p), "publish")
	if err != nil {
		return ""
	}
	var links []string
	lb := s.links(c)
	for _, other := range posts {
		if other.ID == p.ID || gweDocType(other) != typ {
			continue
		}
		for _, oc := range gweConditionsOf(other) {
			if oc == cond {
				links = append(links, `<a href="`+lb.HomeURL(gweEditURL(other.ID))+`" target="_blank">`+htmlEscape(other.Title)+`</a>`)
				break
			}
		}
	}
	if len(links) == 0 {
		return ""
	}
	return "We noticed that you already applied " + strings.Join(links, ", ") + " with the same condition.<br />To continue, set different conditions for each so they don't conflict."
}

// --- query control (autocomplete) --------------------------------------------------------------

// gweProAutocomplete answers the Query control's search: {autocomplete:{object,query,by_field,display}, q}.
func (s *Server) gweProAutocomplete(c *gin.Context, data map[string]any) (any, error) {
	ac, _ := data["autocomplete"].(map[string]any)
	if ac == nil {
		// deprecated shape: filter_type + object_type
		ac = map[string]any{"object": gweStr(data["filter_type"]), "query": map[string]any{"post_type": gweStr(data["object_type"])}}
	}
	q, _ := data["q"].(string)
	q = strings.TrimSpace(q)
	object := gweStr(ac["object"])
	query, _ := ac["query"].(map[string]any)
	results := []map[string]any{}
	add := func(id any, text string) {
		results = append(results, map[string]any{"id": id, "text": text})
	}
	switch object {
	case "post", "library_template", "attachment", "page":
		types := gweProQueryTypes(query, object)
		statuses := []string{"publish", "private"}
		if object == "library_template" {
			types = []string{gweLibrary}
		}
		posts, _, err := s.store.QueryPosts(c, store.PostQuery{Types: types, Statuses: statuses, Search: q, PerPage: 20, Page: 1, OrderBy: "title", Order: "ASC"})
		if err != nil {
			return nil, err
		}
		tplType := ""
		if mq, ok := query["meta_query"].([]any); ok && len(mq) > 0 {
			if m, ok := mq[0].(map[string]any); ok {
				tplType = gweStr(m["value"])
			}
		}
		for _, p := range posts {
			if tplType != "" && gweDocType(p) != tplType {
				continue
			}
			label := p.Title
			if truthyAny(ac["display"]) && gweStr(ac["display"]) == "detailed" {
				label = gweProTypeLabel(p.Type) + ": " + label
			}
			add(p.ID, label)
		}
	case "tax", "term", "cpt_tax":
		tax := gweStr(query["taxonomy"])
		var taxes []string
		switch t := query["taxonomy"].(type) {
		case []any:
			for _, x := range t {
				taxes = append(taxes, gweStr(x))
			}
		default:
			if tax != "" {
				taxes = []string{tax}
			}
		}
		if len(taxes) == 0 {
			taxes = []string{"category", "post_tag"}
		}
		byField := gweStr(ac["by_field"])
		for _, tx := range taxes {
			terms, _, err := s.store.QueryTerms(c, store.TermQuery{Taxonomy: tx, Search: q, PerPage: 20, Page: 1})
			if err != nil {
				continue
			}
			for _, t := range terms {
				var id any = t.ID
				if byField == "slug" {
					id = t.Slug
				}
				label := t.Name
				if len(taxes) > 1 || object == "cpt_tax" {
					label = gweProTaxLabel(tx) + ": " + t.Name
				}
				add(id, label)
			}
		}
	case "author", "user":
		users, _, err := s.store.QueryUsers(c, store.UserQuery{Search: q, PerPage: 20, Page: 1})
		if err != nil {
			return nil, err
		}
		for _, u := range users {
			add(u.ID, u.DisplayName)
		}
	default:
		return nil, gweFail(http.StatusBadRequest, "Invalid autocomplete object.")
	}
	return map[string]any{"results": results}, nil
}

func truthyAny(v any) bool {
	switch t := v.(type) {
	case nil:
		return false
	case bool:
		return t
	case string:
		return t != "" && t != "0"
	case json.Number:
		return t.String() != "0"
	case float64:
		return t != 0
	}
	return true
}

func gweProQueryTypes(query map[string]any, object string) []string {
	var types []string
	switch t := query["post_type"].(type) {
	case string:
		if t != "" && t != "any" {
			types = []string{t}
		}
	case []any:
		for _, x := range t {
			if s := gweStr(x); s != "" && s != "any" {
				types = append(types, s)
			}
		}
	}
	if object == "attachment" {
		return []string{"attachment"}
	}
	if len(types) == 0 {
		return []string{"post", "page"}
	}
	return types
}

func gweProTypeLabel(t string) string {
	switch t {
	case "post":
		return "Post"
	case "page":
		return "Page"
	case "attachment":
		return "Media"
	case gweLibrary:
		return "Template"
	}
	return strings.ToUpper(t[:1]) + t[1:]
}

func gweProTaxLabel(t string) string {
	switch t {
	case "category":
		return "Category"
	case "post_tag":
		return "Tag"
	case "post_format":
		return "Format"
	}
	return t
}

// gweProValueTitles returns the labels of saved Query control values: {get_titles:{object,...}, id:[...]}.
func (s *Server) gweProValueTitles(c *gin.Context, data map[string]any) (any, error) {
	gt, _ := data["get_titles"].(map[string]any)
	if gt == nil {
		gt = map[string]any{"object": gweStr(data["filter_type"])}
	}
	var ids []any
	switch v := data["id"].(type) {
	case []any:
		ids = v
	case nil:
	default:
		ids = []any{v}
	}
	out := map[string]any{}
	object := gweStr(gt["object"])
	query, _ := gt["query"].(map[string]any)
	for _, raw := range ids {
		idStr := gweStr(raw)
		id, _ := strconv.ParseInt(idStr, 10, 64)
		switch object {
		case "post", "library_template", "attachment", "page":
			if p, err := s.store.GetPost(c, id); err == nil {
				out[idStr] = p.Title
			}
		case "tax", "term", "cpt_tax":
			if gweStr(gt["by_field"]) == "slug" {
				tax := gweStr(query["taxonomy"])
				if tax == "" {
					tax = "category"
				}
				if t, err := s.store.TermBySlug(c, tax, idStr); err == nil {
					out[idStr] = t.Name
				}
				continue
			}
			if t, err := s.store.GetTerm(c, id); err == nil {
				out[idStr] = t.Name
			}
		case "author", "user":
			if u, err := s.store.UserByID(c, id); err == nil {
				out[idStr] = u.DisplayName
			}
		}
	}
	return out, nil
}

// --- role manager ------------------------------------------------------------------------------

// gweProUserRestrictions is the editor restriction of the current user's role (Role Manager):
// "" = full access, "content" = content-only editing.
func (s *Server) gweProUserRestrictions(u *store.User) []string {
	if u == nil || u.Can("manage_options", nil) {
		return []string{}
	}
	rm, _ := s.settings.Get("gwe_role_manager").(map[string]any)
	for _, role := range u.Roles {
		if v, ok := rm[role].(map[string]any); ok && truthyAny(v["content_only"]) {
			return []string{"content"}
		}
	}
	return []string{}
}

// gweProRoleExcluded reports whether a user's role is kept out of the editor entirely.
func (s *Server) gweProRoleExcluded(u *store.User) bool {
	if u == nil || u.Can("manage_options", nil) {
		return false
	}
	excl, _ := s.settings.Get("gwe_exclude_user_roles").([]any)
	for _, role := range u.Roles {
		for _, x := range excl {
			if gweStr(x) == role {
				return true
			}
		}
	}
	return false
}

// --- REST --------------------------------------------------------------------------------------

func (s *Server) registerGoWebEditorProREST() {
	// Renderer hooks the Pro widgets read from site settings.
	builder.ProERecaptchaSiteKey = func(v3 bool) string {
		if v3 {
			return s.settings.String("gwe_recaptcha_v3_site_key")
		}
		return s.settings.String("gwe_recaptcha_site_key")
	}
	builder.ProEUsersCanRegister = func() bool { return s.settings.Bool("users_can_register") }
	api := s.rest
	const ns = "elementor-pro/v1"
	editor := func(h restHandler) restHandler {
		return func(c *gin.Context, r *restRequest) {
			u := restCurrent(c)
			if u == nil || !u.Can("edit_posts", nil) {
				restErr(c, http.StatusUnauthorized, "rest_forbidden", "Sorry, you are not allowed to do that.")
				return
			}
			h(c, r)
		}
	}
	// Form submissions hold visitors' personal data: like upstream's submissions controller, only
	// administrators (manage_options) may read or trash them.
	submissions := func(h restHandler) restHandler {
		return func(c *gin.Context, r *restRequest) {
			u := restCurrent(c)
			if u == nil || !u.Can("manage_options", nil) {
				restErr(c, http.StatusForbidden, "rest_forbidden", "Sorry, you are not allowed to do that.")
				return
			}
			h(c, r)
		}
	}
	static := func(v any) restHandler {
		return editor(func(c *gin.Context, _ *restRequest) { c.JSON(http.StatusOK, v) })
	}
	api.register("elementor/v1", "/elementor/v1/global-widget/templates", map[string]restHandler{http.MethodGet: editor(func(c *gin.Context, _ *restRequest) {
		s.gweProGlobalWidgetTemplatesREST(c)
	})}, nil)
	api.register(ns, "/elementor-pro/v1/license/get-license-status", map[string]restHandler{http.MethodGet: static(map[string]any{"isExpired": false})}, nil)
	api.register(ns, "/elementor-pro/v1/license/tier-features", map[string]restHandler{http.MethodGet: static(map[string]any{"features": gweV4TierFeatures, "tier": "agency"})}, nil) // gap-atomic: features unlock e-form / components in the Pro packages
	api.register(ns, "/elementor-pro/v1/get-post-type-taxonomies", map[string]restHandler{http.MethodGet: editor(func(c *gin.Context, _ *restRequest) {
		typ := c.DefaultQuery("post_type", "post")
		out := []map[string]any{}
		if typ == "post" || typ == "any" {
			out = append(out, map[string]any{"name": "category", "label": "Categories", "hierarchical": true},
				map[string]any{"name": "post_tag", "label": "Tags", "hierarchical": false})
		}
		c.JSON(http.StatusOK, map[string]any{"data": out})
	}), http.MethodPost: editor(s.gweLoopPostTypeTaxonomies)}, nil) // gap-loops: POST is the editor's (gowebeditor_loop.go)
	api.register(ns, "/elementor-pro/v1/refresh-loop", map[string]restHandler{http.MethodPost: s.gweLoopRefresh, http.MethodGet: s.gweLoopRefresh}, nil)               // gap-loops
	api.register(ns, "/elementor-pro/v1/refresh-search", map[string]restHandler{http.MethodPost: s.gweLoopRefreshSearch, http.MethodGet: s.gweLoopRefreshSearch}, nil) // gap-loops
	api.register(ns, "/elementor-pro/v1/collection-loop/loop-preview", map[string]restHandler{http.MethodPost: editor(s.gweLoopPreview)}, nil)                         // gap-loops
	api.register(ns, "/elementor-pro/v1/forms/submissions", map[string]restHandler{http.MethodGet: submissions(func(c *gin.Context, _ *restRequest) {
		s.gweProSubmissionsREST(c)
	})}, nil)
	api.register(ns, "/elementor-pro/v1/forms/submissions/(?P<id>\\d+)", map[string]restHandler{http.MethodDelete: submissions(func(c *gin.Context, r *restRequest) {
		id, _ := strconv.ParseInt(r.Params["id"], 10, 64)
		_, err := s.store.Pool.Exec(c, `UPDATE gwe_form_submissions SET status = 'trash' WHERE id = $1`, id)
		if err != nil {
			restErr(c, http.StatusInternalServerError, "rest_error", err.Error())
			return
		}
		c.JSON(http.StatusOK, map[string]any{"success": true})
	})}, nil)
}

// gweProTitleCache caches post titles looked up while rendering.
var gweProTitleCache sync.Map

func htmlEscape(s string) string {
	return strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", `"`, "&quot;", "'", "&#039;").Replace(s)
}

// gweProNewThemePart creates a theme part (gwe_template) for the library's theme document types, so
// headers, footers, singles and archives made from the template library feed the Golementor theme
// builder (gowebeditor_theme*.go) instead of becoming plain library templates.
func (s *Server) gweProNewThemePart(c *gin.Context, tplType string) (*store.Post, bool) {
	switch tplType {
	case "single":
		tplType = "single-post"
	case "page":
		return nil, false
	}
	if gwePartLabel(tplType) == "" {
		return nil, false
	}
	if err := s.gweEnsurePartType(c); err != nil {
		return nil, false
	}
	conds := []any{}
	for _, cd := range gweDefaultConditions[tplType] {
		conds = append(conds, cd)
	}
	p := &store.Post{Type: gwePartType, Title: gwePartLabel(tplType), Status: "draft", AuthorID: currentUser(c).ID, CommentStatus: "closed", PingStatus: "closed",
		Meta: map[string]any{"_elementor_edit_mode": "builder", "_elementor_template_type": tplType, "_elementor_version": gweVersion,
			"_elementor_data": "[]", "_gwe_conditions": conds, "_gwe_theme": ""}}
	if err := s.store.InsertPost(c, p); err != nil {
		return nil, false
	}
	return p, true
}
